import{_ as p,a0 as o,w as r,s as d,ao as l,I as e,x as n,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Zsync：一个仅下载文件新的部分的传输工具 | LCTT x X-CMD","titleTemplate":false,"description":"Zsync：一个仅下载文件新的部分的传输工具 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Zsync：一个仅下载文件新的部分的传输工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Zsync：一个仅下载文件新的部分的传输工具 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180205 A File Transfer Utility To Download Only The New Parts Of A File","title":"Zsync：一个仅下载文件新的部分的传输工具","tag":"201803","desc":""},"relativePath":"201803/20180205 A File Transfer Utility To Download Only The New Parts Of A File.md","filePath":"[post].md"}'),c={name:"201803/20180205 A File Transfer Utility To Download Only The New Parts Of A File.md"};function h(g,s,u,y,k,b){const t=o("Link");return r(),d("div",null,[s[16]||(s[16]=l('<h1 id="zsync-一个仅下载文件新的部分的传输工具" tabindex="-1">Zsync：一个仅下载文件新的部分的传输工具 <a class="header-anchor" href="#zsync-一个仅下载文件新的部分的传输工具" aria-label="Permalink to “Zsync：一个仅下载文件新的部分的传输工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/02/Linux-1-720x340.png" alt=""></p><p>就算是网费每天变得越来越便宜，你也不应该重复下载相同的东西来浪费你的流量。一个很好的例子就是下载 Ubuntu 或任何 Linux 镜像的开发版本。如你所知，Ubuntu 开发人员每隔几个月就会发布一次日常构建、alpha、beta 版 ISO 镜像以供测试。在过去，一旦发布我就会下载这些镜像，并审查每个版本。现在不用了！感谢 Zsync 文件传输程序。现在可以仅下载 ISO 镜像新的部分。这将为你节省大量时间和 Internet 带宽。不仅时间和带宽，它将为你节省服务端和客户端的资源。</p><p>Zsync 使用与 Rsync 相同​​的算法，如果你会得到一份已有文件旧版本，它只下载该文件新的部分。 Rsync 主要用于在计算机之间同步数据，而 Zsync 则用于分发数据。简单地说，可以使用 Zsync 将中心的一个文件分发给数千个下载者。它在 Artistic License V2 许可证下发布，完全免费且开源。</p><h3 id="安装-zsync" tabindex="-1">安装 Zsync <a class="header-anchor" href="#安装-zsync" aria-label="Permalink to “安装 Zsync”">​</a></h3><p>Zsync 在大多数 Linux 发行版的默认仓库中有。</p><p>在 Arch Linux 及其衍生版上，使用命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S zsync</span></span></code></pre></div><p>在 Fedora 上，启用 Zsync 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf copr enable ngompa/zsync</span></span></code></pre></div><p>并使用命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install zsync</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install zsync</span></span></code></pre></div>',14)),e("p",null,[s[1]||(s[1]=n("对于其他发行版，你可以从 ",-1)),i(t,{href:"http://zsync.moria.org.uk/downloads"},{default:a(()=>[...s[0]||(s[0]=[n("Zsync 下载页面",-1)])]),_:1}),s[2]||(s[2]=n("下载二进制打包文件，并手动编译安装它，如下所示。",-1))]),s[17]||(s[17]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://zsync.moria.org.uk/download/zsync-0.6.2.tar.bz2</span></span>
<span class="line"><span>$ tar xjf zsync-0.6.2.tar.bz2</span></span>
<span class="line"><span>$ cd zsync-0.6.2/</span></span>
<span class="line"><span>$ configure</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>请注意，只有当人们提供 zsync 下载方式时，zsync 才有用。目前，Debian、Ubuntu（所有版本）的 ISO 镜像都有 .zsync 下载链接。例如，请访问以下链接。</p><p>你可能注意到，Ubuntu 18.04 LTS 每日构建版有直接的 ISO 和 .zsync 文件。如果你下载 .ISO 文件，则必须在 ISO 更新时下载完整的 ISO 文件。但是，如果你下载的是 .zsync 文件，那么 Zsync 以后仅会下载新的更改。你不需要每次都下载整个 ISO 映像。</p><p>.zsync 文件包含 zsync 程序所需的元数据。该文件包含 rsync 算法的预先计算的校验和。它在服务器上生成一次，然后由任意数量的下载器使用。要使用 Zsync 客户端程序下载 .zsync 文件，你只需执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zsync &lt;.zsync-file-URL&gt;</span></span></code></pre></div><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zsync http://cdimage.ubuntu.com/ubuntu/daily-live/current/bionic-desktop-amd64.iso.zsync</span></span></code></pre></div><p>如果你的系统中已有以前的镜像文件，那么 Zsync 将计算远程服务器中旧文件和新文件之间的差异，并仅下载新的部分。你将在终端看见计算过程一系列的点或星星。</p><p>如果你下载的文件的旧版本存在于当前工作目录，那么 Zsync 将只下载新的部分。下载完成后，你将看到两个镜像，一个你刚下载的镜像和以 .iso.zs-old 为扩展名的旧镜像。</p><p>如果没有找到相关的本地数据，Zsync 会下载整个文件。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/02/Zsync-1.png" alt=""></p><p>你可以随时按 <code>CTRL-C</code> 取消下载过程。</p><p>试想一下，如果你直接下载 .ISO 文件或使用 torrent，每当你下载新镜像时，你将损失约 1.4GB 流量。因此，Zsync 不会下载整个 Alpha、beta 和日常构建映像，而只是在你的系统上下载了 ISO 文件的新部分，并在系统中有一个旧版本的拷贝。</p><p>今天就到这里。希望对你有帮助。我将很快另外写一篇有用的指南。在此之前，请保持关注！</p><p>干杯！</p><hr>`,17)),e("p",null,[s[4]||(s[4]=n("via: ",-1)),i(t,{href:"https://www.ostechnix.com/zsync-file-transfer-utility-download-new-parts-file/"},{default:a(()=>[...s[3]||(s[3]=[n("https://www.ostechnix.com/zsync-file-transfer-utility-download-new-parts-file/",-1)])]),_:1})]),e("p",null,[s[8]||(s[8]=n("作者：",-1)),i(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[5]||(s[5]=[n("SK",-1)])]),_:1}),s[9]||(s[9]=n(" 译者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:a(()=>[...s[6]||(s[6]=[n("geekpi",-1)])]),_:1}),s[10]||(s[10]=n(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[13]||(s[13]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[11]||(s[11]=[n("LCTT",-1)])]),_:1}),s[14]||(s[14]=n(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:a(()=>[...s[12]||(s[12]=[n("Linux中国",-1)])]),_:1}),s[15]||(s[15]=n(" 荣誉推出",-1))])])}const w=p(c,[["render",h]]);export{T as __pageData,w as default};
